use crate::bson_values;
use crate::bson_values::Loaded;
use mongodb::bson::Document;
use mongodb::error::Error;

/// A document of the "posts" collection. A field stays `None` until it is set or read.
#[derive(Debug, Clone, Default, PartialEq)]
pub struct Post {
    pub id: Option<uuid::Uuid>,
    pub title: Option<String>,
    pub author: Option<uuid::Uuid>,
    pub published_at: Option<chrono::DateTime<chrono::Utc>>,
    pub comments: Option<Vec<PostComment>>,
    /// As it was read: a change writes only what differs
    pub loaded: Loaded,
}

impl Post {
    /// What a document holds.
    pub fn from_document(document: &Document) -> Result<Self, Error> {
        let mut entity = Post {
            id: bson_values::read(document, "_id", bson_values::as_uuid)?,
            title: bson_values::read(document, "title", bson_values::as_text)?,
            author: bson_values::read(document, "author", bson_values::as_uuid)?,
            published_at: bson_values::read(document, "published_at", bson_values::as_moment)?,
            comments: bson_values::read(document, "comments", bson_values::as_list(bson_values::as_nested(PostComment::from_document)))?,
            loaded: Loaded::default(),
        };
        entity.loaded = Loaded(Some(entity.to_document()?));
        Ok(entity)
    }

    /// Its document: what is None is left out.
    pub fn to_document(&self) -> Result<Document, Error> {
        let mut document = Document::new();
        bson_values::write(&mut document, "_id", &self.id, bson_values::of_uuid)?;
        bson_values::write(&mut document, "title", &self.title, bson_values::of_text)?;
        bson_values::write(&mut document, "author", &self.author, bson_values::of_uuid)?;
        bson_values::write(&mut document, "published_at", &self.published_at, bson_values::of_moment)?;
        bson_values::write(&mut document, "comments", &self.comments, bson_values::of_list(bson_values::of_nested(PostComment::to_document)))?;
        Ok(document)
    }
}

/// A nested document: it is stored with the one that holds it.
#[derive(Debug, Clone, Default, PartialEq)]
pub struct PostComment {
    pub id: Option<uuid::Uuid>,
    pub text: Option<String>,
    pub marks: Option<Vec<uuid::Uuid>>,
}

impl PostComment {
    /// What a document holds.
    pub fn from_document(document: &Document) -> Result<Self, Error> {
        Ok(PostComment {
            id: bson_values::read(document, "id", bson_values::as_uuid)?,
            text: bson_values::read(document, "text", bson_values::as_text)?,
            marks: bson_values::read(document, "marks", bson_values::as_list(bson_values::as_uuid))?,
        })
    }

    /// Its document: what is None is left out.
    pub fn to_document(&self) -> Result<Document, Error> {
        let mut document = Document::new();
        bson_values::write(&mut document, "id", &self.id, bson_values::of_uuid)?;
        bson_values::write(&mut document, "text", &self.text, bson_values::of_text)?;
        bson_values::write(&mut document, "marks", &self.marks, bson_values::of_list(bson_values::of_uuid))?;
        Ok(document)
    }
}

