#[async_trait]
pub trait AuthorRepository: Send + Sync {
    /// The row with this primary key, or None.
    async fn find_by_id(&self, id: uuid::Uuid) -> Result<Option<Author>, DomainError>;

    /// At most limit rows from offset, by primary key, and how many there are.
    async fn list(&self, offset: u64, limit: u64) -> Result<Page<Author>, DomainError>;

