    async fn insert(&self, entity: Author) -> Result<Author, DomainError>;

    /// Stores the changes made to a row.
    async fn update(&self, entity: Author) -> Result<Author, DomainError>;

    /// Removes a row.
    async fn delete(&self, entity: &Author) -> Result<(), DomainError>;
}

/// Keeps authors rows in the database, through the MongoDB driver: on the connection of the unit of work, or in its transaction.
pub struct MongoAuthorRepository<'a> {
    db: &'a Db,
}

impl<'a> MongoAuthorRepository<'a> {
    pub fn new(db: &'a Db) -> Self {
        Self { db }
    }
}

#[async_trait]
impl AuthorRepository for MongoAuthorRepository<'_> {
    async fn find_by_id(&self, id: uuid::Uuid) -> Result<Option<Author>, DomainError> {
        let found = self.db.find_one("authors", doc! { "_id": bson_values::of_uuid(&id)? }).await?;
        Ok(found.as_ref().map(Author::from_document).transpose()?)
    }

    async fn list(&self, offset: u64, limit: u64) -> Result<Page<Author>, DomainError> {
        let total = self.db.count("authors", doc! {}).await?;
        let found = if limit > 0 {
            self.db.find("authors", doc! {}, doc! { "_id": 1 }, offset, limit).await?
        } else {
            Vec::new()
        };
        Ok(Page { items: found.iter().map(Author::from_document).collect::<Result<_, _>>()?, total, offset, limit })
    }

    async fn insert(&self, entity: Author) -> Result<Author, DomainError> {
        let mut entity = entity;
        let document = entity.to_document()?;
        self.db.insert("Author", "authors", &document).await?;
        entity.loaded = Loaded(Some(document));
        Ok(entity)
    }

    async fn update(&self, entity: Author) -> Result<Author, DomainError> {
        let mut entity = entity;
        let now = entity.to_document()?;
        let changes = bson_values::changes(entity.loaded.0.as_ref(), &now, &["email"]);
        if !changes.is_empty() {
            self.db.update("Author", "authors", doc! { "_id": now.get("_id").cloned() }, changes).await?;
        }
        entity.loaded = Loaded(Some(now));
        Ok(entity)
    }

    async fn delete(&self, entity: &Author) -> Result<(), DomainError> {
        let id = entity.id.expect("id is set");
        self.db.delete("Author", "authors", doc! { "_id": bson_values::of_uuid(&id)? }).await
    }
}

/// Keeps authors rows in memory, for tests and for trying the services without a database. Its copies share the rows.
#[derive(Clone, Default)]
pub struct MemoryAuthorRepository {
    rows: Arc<Mutex<Vec<Author>>>,
}

impl MemoryAuthorRepository {
    /// The rows reads see, by primary key.
    fn visible(&self) -> Vec<Author> {
        let mut rows: Vec<Author> = self.rows.lock().unwrap().iter().cloned().collect();
        rows.sort_by(|a, b| key_of(a).partial_cmp(&key_of(b)).unwrap_or(Ordering::Equal));
        rows
    }

    /// Keeps a row, in place of the one with its key.
    fn store(&self, entity: &Author) {
        let mut rows = self.rows.lock().unwrap();
        rows.retain(|row| key_of(row) != key_of(entity));
        rows.push(entity.clone());
    }
}

/// The key of a row, as a tuple of its key values.
fn key_of(row: &Author) -> (Option<uuid::Uuid>,) {
    (row.id,)
}

#[async_trait]
impl AuthorRepository for MemoryAuthorRepository {
    async fn find_by_id(&self, id: uuid::Uuid) -> Result<Option<Author>, DomainError> {
        Ok(self.visible().into_iter().find(|row| row.id.as_ref() == Some(&id)))
    }

    async fn list(&self, offset: u64, limit: u64) -> Result<Page<Author>, DomainError> {
        let rows = self.visible();
        let total = rows.len() as u64;
        Ok(Page { items: rows.into_iter().skip(offset as usize).take(limit as usize).collect(), total, offset, limit })
    }

    async fn insert(&self, entity: Author) -> Result<Author, DomainError> {
        self.store(&entity);
        Ok(entity)
    }

    async fn update(&self, entity: Author) -> Result<Author, DomainError> {
        self.store(&entity);
        Ok(entity)
    }

    async fn delete(&self, entity: &Author) -> Result<(), DomainError> {
        self.rows.lock().unwrap().retain(|row| key_of(row) != key_of(entity));
        Ok(())
    }
}

