        let tail = doc! { "$slice": ["$comments", position as i64 + 1, size.max(1) as i64] };
        let change = vec![doc! { "$set": { "comments": { "$concatArrays": [head, tail] } } }];
        let changed = self.db.change("Post", "posts", doc! { "_id": bson_values::of_uuid(&id)?, "comments": { "$size": size as i64 } }, change).await?;
