impl PostRepository for MemoryPostRepository {
    async fn find_by_id(&self, id: uuid::Uuid) -> Result<Option<Post>, DomainError> {
        Ok(self.visible().into_iter().find(|row| row.id.as_ref() == Some(&id)))
    }

