        Ok(self.visible().into_iter().filter(|row| row.author.as_ref() == Some(&author)).collect())
    }

    async fn insert(&self, entity: Post) -> Result<Post, DomainError> {
        self.store(&entity);
        Ok(entity)
    }

    async fn update(&self, entity: Post) -> Result<Post, DomainError> {
        self.store(&entity);
        Ok(entity)
    }

    async fn delete(&self, entity: &Post) -> Result<(), DomainError> {
        self.rows.lock().unwrap().retain(|row| key_of(row) != key_of(entity));
        Ok(())
    }

    async fn add_comment(&self, id: uuid::Uuid, comment: crate::entities::post::PostComment) -> Result<Option<Post>, DomainError> {
        let Some(mut found) = self.visible().into_iter().find(|row| row.id.as_ref() == Some(&id)) else {
            return Ok(None);
        };
        found.comments.get_or_insert_default().push(comment);
        self.store(&found);
        Ok(Some(found))
    }

    async fn remove_comment(&self, id: uuid::Uuid, position: usize, size: usize) -> Result<Option<Post>, DomainError> {
        let Some(mut found) = self.visible().into_iter().find(|row| row.id.as_ref() == Some(&id)) else {
            return Ok(None);
        };
        let items = found.comments.get_or_insert_default();
        if items.len() != size || position >= size {
            return Ok(None);
        }
        items.remove(position);
        self.store(&found);
        Ok(Some(found))
    }
}

