//! The service of the "authors" table.

use crate::common::Page;
use crate::entities::author::Author;
use crate::errors::{DomainError, FieldError};
use crate::unit_of_work::UnitOfWork;
use std::sync::Arc;

/// The values of a Author that change: fields left Absent keep their value; Patch::Set(None) empties one.
#[derive(Debug, Clone, Default, PartialEq)]
pub struct AuthorChanges {
    pub email: crate::common::Patch<Option<String>>,
}

/// Operations on authors. Repositories commit every write.
pub struct AuthorService {
    unit_of_work: Arc<dyn UnitOfWork>,
}

impl AuthorService {
    pub fn new(unit_of_work: Arc<dyn UnitOfWork>) -> Self {
        Self { unit_of_work }
    }

    /// Stores a new Author after checking it.
    pub async fn create_author(&self, author: Author) -> Result<Author, DomainError> {
        let values = Values { id: author.id.map(Some), email: author.email.map(Some) };
        let uow = self.unit_of_work.as_ref();
        check_values(uow, &values, None).await?;
        let mut entity = Author::default();
        apply_values(&mut entity, &values);
        let created = uow.authors().insert(entity).await?;
        Ok(created)
    }

    /// The Author with this key; NotFound when there is none.
    pub async fn get_author(&self, id: uuid::Uuid) -> Result<Author, DomainError> {
        find(self.unit_of_work.as_ref(), id).await
    }

    /// A page of authors, by primary key.
    pub async fn list_authors(&self, offset: u64, limit: u64) -> Result<Page<Author>, DomainError> {
        self.unit_of_work.authors().list(offset, limit).await
    }

    /// Changes the given values of a Author.
    pub async fn update_author(&self, id: uuid::Uuid, changes: AuthorChanges) -> Result<Author, DomainError> {
        let values = given(changes);
        let uow = self.unit_of_work.as_ref();
        let mut current = find(uow, id).await?;
        check_values(uow, &values, Some(&current)).await?;
        apply_values(&mut current, &values);
        let updated = uow.authors().update(current).await?;
        Ok(updated)
    }

    /// Deletes a Author.
    pub async fn delete_author(&self, id: uuid::Uuid) -> Result<(), DomainError> {
        let uow = self.unit_of_work.as_ref();
        let current = find(uow, id).await?;
        if !uow.posts().list_by_author(current.id.expect("id is set")).await?.is_empty() {
            return Err(DomainError::conflict("Author", "rows of posts still point to it", &["posts"]));
        }
        uow.authors().delete(&current).await?;
        Ok(())
    }
}

/// The values a create or an update gives, by field: None when not given, Some(None) when given empty.
#[derive(Default)]
struct Values {
    id: Option<Option<uuid::Uuid>>,
    email: Option<Option<String>>,
}

/// Checks the values against the rules of the "authors" table, and the rows they point to; ValidationFailed lists every problem.
async fn validate(_uow: &dyn UnitOfWork, values: &Values, current: Option<&Author>) -> Result<(), DomainError> {
    let creating = current.is_none();
    let mut errors = Vec::new();
    match values.id.as_ref().and_then(|value| value.as_ref()) {
        None => {
            if creating || values.id.is_some() {
                errors.push(FieldError::new("_id", "is required"));
            }
        }
        Some(_) => {}
    }
    match values.email.as_ref().and_then(|value| value.as_ref()) {
        None => {
            if creating || values.email.is_some() {
                errors.push(FieldError::new("email", "is required"));
            }
        }
        Some(_) => {}
    }
    if errors.is_empty() {
        Ok(())
    } else {
        Err(DomainError::ValidationFailed { entity: "Author".to_string(), errors })
    }
}

/// Every check before a write: the values, the rows they point to, the unique values.
async fn check_values(uow: &dyn UnitOfWork, values: &Values, current: Option<&Author>) -> Result<(), DomainError> {
    validate(uow, values, current).await?;
    Ok(())
}

/// Sets the given values on the entity.
fn apply_values(entity: &mut Author, values: &Values) {
    if let Some(value) = &values.id {
        entity.id = *value;
    }
    if let Some(value) = &values.email {
        entity.email = value.clone();
    }
}

/// The values an update gives, by field.
fn given(changes: AuthorChanges) -> Values {
    Values { email: changes.email.given(), ..Default::default() }
}

/// The Author with this key; NotFound when there is none.
async fn find(uow: &dyn UnitOfWork, id: uuid::Uuid) -> Result<Author, DomainError> {
    uow.authors().find_by_id(id).await?.ok_or_else(|| DomainError::not_found("Author", id))
}

