/// Operations on posts. Repositories commit every write.
pub struct PostService {
    unit_of_work: Arc<dyn UnitOfWork>,
}

impl PostService {
    pub fn new(unit_of_work: Arc<dyn UnitOfWork>) -> Self {
        Self { unit_of_work }
    }

    /// Stores a new Post after checking it.
    pub async fn create_post(&self, post: Post) -> Result<Post, DomainError> {
        let values = Values { id: post.id.map(Some), title: post.title.map(Some), author: post.author.map(Some), published_at: post.published_at.map(Some), comments: post.comments.map(Some) };
        let uow = self.unit_of_work.as_ref();
        check_values(uow, &values, None).await?;
        let mut entity = Post::default();
        apply_values(&mut entity, &values);
        let created = uow.posts().insert(entity).await?;
        Ok(created)
    }

    /// The Post with this key; NotFound when there is none.
    pub async fn get_post(&self, id: uuid::Uuid) -> Result<Post, DomainError> {
        find(self.unit_of_work.as_ref(), id).await
    }

    /// A page of posts, by primary key.
    pub async fn list_posts(&self, offset: u64, limit: u64) -> Result<Page<Post>, DomainError> {
        self.unit_of_work.posts().list(offset, limit).await
    }

    /// Changes the given values of a Post.
    pub async fn update_post(&self, id: uuid::Uuid, changes: PostChanges) -> Result<Post, DomainError> {
        let values = given(changes);
        let uow = self.unit_of_work.as_ref();
        let mut current = find(uow, id).await?;
        check_values(uow, &values, Some(&current)).await?;
        apply_values(&mut current, &values);
        let updated = uow.posts().update(current).await?;
        Ok(updated)
    }

    /// Deletes a Post.
    pub async fn delete_post(&self, id: uuid::Uuid) -> Result<(), DomainError> {
        let uow = self.unit_of_work.as_ref();
        let current = find(uow, id).await?;
        uow.posts().delete(&current).await?;
        Ok(())
    }

    /// The posts with this author.
    pub async fn list_posts_by_author(&self, author: uuid::Uuid) -> Result<Vec<Post>, DomainError> {
        self.unit_of_work.posts().list_by_author(author).await
    }

    /// Adds an item to comments.
    pub async fn add_comment(&self, id: uuid::Uuid, comment: crate::entities::post::PostComment) -> Result<Post, DomainError> {
        let mut errors: Vec<FieldError> = Vec::new();
        check_post_comment(&comment, "comments", &mut errors);
        if !errors.is_empty() {
            return Err(DomainError::ValidationFailed { entity: "Post".to_string(), errors });
        }
        let uow = self.unit_of_work.as_ref();
        find(uow, id).await?;
        let changed = uow.posts().add_comment(id, comment).await?.ok_or_else(|| DomainError::not_found("Post", id))?;
        Ok(changed)
    }

    /// Removes an item from comments, by its position.
    pub async fn remove_comment(&self, id: uuid::Uuid, position: usize) -> Result<Post, DomainError> {
        let uow = self.unit_of_work.as_ref();
        let current = find(uow, id).await?;
        if !(position < current.comments.as_deref().unwrap_or_default().len()) {
            return Err(DomainError::not_found("Comment", position));
        }
        let size = current.comments.as_deref().unwrap_or_default().len();
        let changed = uow.posts().remove_comment(id, position, size).await?.ok_or_else(|| DomainError::conflict("Post", "was changed by someone else since it was read", &["comments"]))?;
        Ok(changed)
    }
}

/// The values a create or an update gives, by field: None when not given, Some(None) when given empty.
#[derive(Default)]
struct Values {
    id: Option<Option<uuid::Uuid>>,
    title: Option<Option<String>>,
    author: Option<Option<uuid::Uuid>>,
    published_at: Option<Option<chrono::DateTime<chrono::Utc>>>,
    comments: Option<Option<Vec<crate::entities::post::PostComment>>>,
}

/// Checks the values against the rules of the "posts" table, and the rows they point to; ValidationFailed lists every problem.
async fn validate(uow: &dyn UnitOfWork, values: &Values, current: Option<&Post>) -> Result<(), DomainError> {
    let creating = current.is_none();
    let mut errors = Vec::new();
    match values.id.as_ref().and_then(|value| value.as_ref()) {
        None => {
            if creating || values.id.is_some() {
                errors.push(FieldError::new("_id", "is required"));
            }
        }
        Some(_) => {}
    }
    match values.title.as_ref().and_then(|value| value.as_ref()) {
        None => {
            if creating || values.title.is_some() {
                errors.push(FieldError::new("title", "is required"));
            }
        }
        Some(_) => {}
    }
    match values.author.as_ref().and_then(|value| value.as_ref()) {
        None => {
            if creating || values.author.is_some() {
                errors.push(FieldError::new("author", "is required"));
            }
        }
        Some(_) => {}
    }
    match values.comments.as_ref().and_then(|value| value.as_ref()) {
        None => {
            if creating || values.comments.is_some() {
                errors.push(FieldError::new("comments", "is required"));
            }
        }
        Some(value) => {
            for (i0, item0) in value.iter().enumerate() {
                check_post_comment(item0, &format!("comments.{i0}"), &mut errors);
            }
        }
    }
    {
        let author = values.author.clone().unwrap_or_else(|| current.and_then(|current| current.author));
        if let Some(author) = author {
            if uow.authors().find_by_id(author).await?.is_none() {
                errors.push(FieldError::new("author", "no Author has this key"));
            }
        }
    }
    if errors.is_empty() {
        Ok(())
    } else {
        Err(DomainError::ValidationFailed { entity: "Post".to_string(), errors })
    }
}

/// Every check before a write: the values, the rows they point to, the unique values.
async fn check_values(uow: &dyn UnitOfWork, values: &Values, current: Option<&Post>) -> Result<(), DomainError> {
    validate(uow, values, current).await?;
    Ok(())
}

/// Sets the given values on the entity.
fn apply_values(entity: &mut Post, values: &Values) {
    if let Some(value) = &values.id {
        entity.id = *value;
    }
    if let Some(value) = &values.title {
        entity.title = value.clone();
    }
    if let Some(value) = &values.author {
        entity.author = *value;
    }
    if let Some(value) = &values.published_at {
        entity.published_at = *value;
    }
    if let Some(value) = &values.comments {
        entity.comments = value.clone();
    }
}

/// What a PostComment does not follow of its rules, each with the path of its field.
fn check_post_comment(value: &crate::entities::post::PostComment, path: &str, errors: &mut Vec<FieldError>) {
    if value.id.is_none() {
        errors.push(FieldError::new(&format!("{path}.id"), "is required"));
    }
    if value.text.is_none() {
        errors.push(FieldError::new(&format!("{path}.text"), "is required"));
    }
    if value.marks.is_none() {
        errors.push(FieldError::new(&format!("{path}.marks"), "is required"));
    }
}

/// The values an update gives, by field.
fn given(changes: PostChanges) -> Values {
    Values { title: changes.title.given(), author: changes.author.given(), published_at: changes.published_at.given(), comments: changes.comments.given(), ..Default::default() }
}

/// The Post with this key; NotFound when there is none.
async fn find(uow: &dyn UnitOfWork, id: uuid::Uuid) -> Result<Post, DomainError> {
    uow.posts().find_by_id(id).await?.ok_or_else(|| DomainError::not_found("Post", id))
}

