async fn stores_the_changes() {
    let (_turn, uow) = database::open().await;
    let mut stored = factories::add_author(&uow, 1).await;
    stored.email = Some("changed".to_string());
    uow.authors().update(stored.clone()).await.expect("an update");
    let found = uow.authors().find_by_id(stored.id.expect("id is set")).await.expect("a read");
