    let (_turn, uow) = database::open().await;
    let stored = factories::add_author(&uow, 1).await;
    uow.authors().delete(&stored).await.expect("a delete");
    assert!(uow.authors().find_by_id(stored.id.expect("id is set")).await.expect("a read").is_none());
}

