/// A valid Author that is not stored yet; n makes its unique values differ.
pub fn new_author(n: i32) -> Author {
    Author {
        id: Some(uuid::Uuid::from_u128(n as u128)),
        email: Some(format!("email-{n}")),
        ..Default::default()
    }
}

/// A stored Author.
pub async fn add_author(uow: &dyn UnitOfWork, n: i32) -> Author {
    let entity = new_author(n);
    uow.authors().insert(entity).await.expect("a stored Author")
}

/// A valid Post that is not stored yet; n makes its unique values differ.
pub fn new_post(n: i32) -> Post {
    Post {
        id: Some(uuid::Uuid::from_u128(n as u128)),
        title: Some(format!("title-{n}")),
        published_at: Some(chrono::NaiveDate::from_ymd_opt(2026, 1, (n % 28 + 1) as u32).expect("a date").and_hms_opt(12, 0, 0).expect("a time").and_utc()),
        comments: Some(vec![new_post_comment(n)]),
        ..Default::default()
    }
}

/// A stored Post, with the rows it points to.
pub async fn add_post(uow: &dyn UnitOfWork, n: i32) -> Post {
    let parent0 = add_author(uow, n).await;
    let mut entity = new_post(n);
    entity.author = parent0.id;
    uow.posts().insert(entity).await.expect("a stored Post")
}

