#[tokio::test]
async fn adds_and_removes_one_item_of_comments() {
    let uow = Arc::new(MemoryUnitOfWork::default());
    let service = PostService::new(uow.clone());
    let parent0 = factories::add_author(uow.as_ref(), 100).await;
    let mut row = factories::new_post(1);
    row.author = parent0.id;
    let created = service.create_post(row).await.expect("a create");
    let before = created.comments.as_ref().map_or(0, Vec::len);
    let n = 7;
    let item: mongorust_mongodb_from_model2db::entities::post::PostComment = factories::new_post_comment(n);
    let added = service.add_comment(created.id.expect("id is set"), item).await.expect("a write");
    assert_eq!(before + 1, added.comments.as_ref().map_or(0, Vec::len));
    let removed = service.remove_comment(created.id.expect("id is set"), before).await.expect("a write");
    assert_eq!(before, removed.comments.as_ref().map_or(0, Vec::len));
    assert!(matches!(service.remove_comment(created.id.expect("id is set"), 99).await, Err(DomainError::NotFound { .. })));
}
